INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(5301, 'Deuteronomy 31:17', 'Deuteronomy', 31, 17, '&nbsp;نو بيا به زۀ هغوئ ته په قهر شم، زۀ به هغوئ پرېږدم او هغوئ به تباه شى. ډېر سخت افتونه به په هغوئ راشى، نو هغوئ ته به پته ولګى چې په هغوئ باندې داسې ځکه کيږى چې زۀ يعنې خُدائ پاک نور د هغوئ مل نۀ يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5302, 'Deuteronomy 31:18', 'Deuteronomy', 31, 18, '&nbsp;نو په هغه وخت به زۀ د هغوئ نه مخ واړوم، ځکه چې هغوئ به بد عمل کړے وى او د نورو معبودانو عبادت به يې کړے وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5303, 'Deuteronomy 31:19', 'Deuteronomy', 31, 19, '&nbsp;اوس دا سندره وليکه. دا د بنى اِسرائيلو خلقو ته وښايه او ور زده يې کړه، نو چې دا د هغوئ خِلاف د ګواه په شان وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5304, 'Deuteronomy 31:20', 'Deuteronomy', 31, 20, '&nbsp;زۀ به هغوئ هغه مُلک ته بوځم چې زرخېز او آباد دے، لکه څنګه چې ما د هغوئ د پلار نيکۀ سره وعده کړې ده. هغوئ چې څومره خوراک غواړى نو هلته به ورته ملاويږى او هغوئ به په آرام سره ژوند تېروى. خو هغوئ به واوړى او د نورو معبودانو عبادت به وکړى. زما نه به هغوئ منکر شى او زما لوظ به مات کړى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5305, 'Deuteronomy 31:21', 'Deuteronomy', 31, 21, '&nbsp;او کله چې په هغوئ باندې سخت افتونه او مصيبتونه راشى نو دا سندره به د هغوئ خِلاف ګواه وى، ځکه چې د هغوئ اولاد به دا نۀ هېروى. ما ته د هغوئ د ارادې پته ده چې هغوئ مې لا وعده کړے شوى مُلک ته راوستلى هم نۀ دى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5306, 'Deuteronomy 31:22', 'Deuteronomy', 31, 22, '&nbsp;نو هم په هغه ورځ موسىٰ دا سندره وليکله او په بنى اِسرائيلو باندې يې زده کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5307, 'Deuteronomy 31:23', 'Deuteronomy', 31, 23, '&nbsp;بيا مالِک خُدائ د نون زوئ يشوَع سره خبرې وکړې او ورته يې وفرمائيل، ”تکړه او زړَور اوسه. تۀ به اِسرائيليان هغه مُلک ته بوځې چې ما د هغوئ سره د هغې وعده کړې ده او زۀ به ستا مل يم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5308, 'Deuteronomy 31:24', 'Deuteronomy', 31, 24, '&nbsp;نو موسىٰ د خُدائ پاک مکمل حُکمونه په يو کِتاب کښې وليکل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5309, 'Deuteronomy 31:25', 'Deuteronomy', 31, 25, '&nbsp;کله چې هغه اوزګار شو، نو هغۀ ليويانو اِمامانو ته وفرمائيل کوم چې د مالِک خُدائ د لوظ صندوق مشران وُو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5310, 'Deuteronomy 31:26', 'Deuteronomy', 31, 26, '&nbsp;”د خُدائ پاک د قانون دا کِتاب واخلئ او د مالِک خُدائ ستاسو خُدائ پاک د لوظ صندوق په خوا کښې يې کېږدئ، چې دا د خپلو خلقو خِلاف د يو ګواه په شان وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5311, 'Deuteronomy 31:27', 'Deuteronomy', 31, 27, '&nbsp;ما ته پته ده چې هغوئ څومره ضدى او سرکشه دى. هغوئ زما په ژوند کښې د مالِک خُدائ خِلاف بغاوت کړے دے او زما د مرګ نه پس به هغوئ نور بغاوت هم کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5312, 'Deuteronomy 31:28', 'Deuteronomy', 31, 28, '&nbsp;د قبيلو ټول مشران او آفسران زما په وړاندې راغونډ کړئ، چې زۀ هغوئ ته دا خبرې وښايم، زۀ به آسمان او زمکه د هغوئ خِلاف ګواهان جوړ کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5313, 'Deuteronomy 31:29', 'Deuteronomy', 31, 29, '&nbsp;ما ته پته ده چې زما د مرګ نه پس به خلق بدعمله شى او چې ما څۀ ورته ښودلى دى د هغې نه به منکر شى. او په راتلونکى وخت کښې به هغوئ د افت سره مخامخ شى، ځکه چې هغوئ به مالِک خُدائ په قهر کړے وى د هغه کارونو په وجه چې هغۀ منع کړى دى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5314, 'Deuteronomy 31:30', 'Deuteronomy', 31, 30, '&nbsp;بيا موسىٰ حمد ووئيلو او د بنى اِسرائيلو ټول قوم ورته غوږ اېښے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5315, 'Deuteronomy 32:1', 'Deuteronomy', 32, 1, '&nbsp;اے آسمانونو. ما ته غوږ کېږدئ او زۀ به خبرې وکړم، اے زمکې زما د خولې خبرې واوره.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5316, 'Deuteronomy 32:2', 'Deuteronomy', 32, 2, '&nbsp;زما تعليمات به د باران په شان راپرېوځى، او زما پېغام به د پرخې په شان راکوزيږى. پرېږده چې زما خبرې په تازه واښو باندې د باران په شان راپرېوځى، او چې د نرى باران په شان په شنو بوټو باندې ووريږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5317, 'Deuteronomy 32:3', 'Deuteronomy', 32, 3, '&nbsp;زۀ به د مالِک خُدائ د نوم بيان وکړم، زمونږ د خُدائ پاک لوئى بيان کړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5318, 'Deuteronomy 32:4', 'Deuteronomy', 32, 4, '&nbsp;مالِک خُدائ طاقتور ساتونکے دے، د هغۀ کارونه مکمل دى او د هغۀ هر کار د اِنصاف دے، ستاسو خُدائ پاک وفادار او رښتونے دے، هغه صادق او اِنصاف کوونکے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5319, 'Deuteronomy 32:5', 'Deuteronomy', 32, 5, '&nbsp;خو تاسو بې‌وفا يئ او د دې لائق نۀ يئ چې د هغۀ خلق شئ، تاسو ګناهګار او دوکه باز قوم يئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5320, 'Deuteronomy 32:6', 'Deuteronomy', 32, 6, '&nbsp;تاسو د مالِک خُدائ سره داسې کوئ، اے کم عقلو او بې‌شعوره خلقو. هغه ستاسو پلار دے، هغه ستاسو خالِق دے، هغۀ تاسو جوړ کړئ او آباد يې کړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5321, 'Deuteronomy 32:7', 'Deuteronomy', 32, 7, '&nbsp;تاريخ ته وګورئ، هغه وخت چې پخوا تېر شوے دے، د خپل پلار نيکۀ نه تپوس وکړئ نو هغه به درته ووائى چې څۀ شوى وُو، د خپلو مشرانو نه تپوس وکړئ، هغوئ به مو د تېرې زمانې نه خبر کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5322, 'Deuteronomy 32:8', 'Deuteronomy', 32, 8, '&nbsp;خُدائ تعالىٰ قومونو له خپل خپل ميراث ورکړو، کله چې هغۀ فېصله وکړه چې قومونه به په کوم کوم ځائ کښې اوسيږى، چې هر يو قوم د خپل هغه معبود سره اوسيږى چې هغۀ ورله خوښ کړے وى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5323, 'Deuteronomy 32:9', 'Deuteronomy', 32, 9, '&nbsp;خو د يعقوب اولاد هغۀ د خپل ځان دپاره خوښ کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5324, 'Deuteronomy 32:10', 'Deuteronomy', 32, 10, '&nbsp;هغۀ هغوئ په بيابان کښې پېدا کړل چې سرګردانه ګرځېدل، چې يوه خوشې او اوچه صحرا وه. هغۀ هغوئ بچ کړل او پام يې ورباندې وکړو، لکه چې هغه يې د سترګو تور وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5325, 'Deuteronomy 32:11', 'Deuteronomy', 32, 11, '&nbsp;لکه چې يو باز خپل بچى ته د الوتلو چل ښائى، او په حِفاظت سره يې په خورو وزرو کښې نيسى، مالِک خُدائ اِسرائيليان د غورزېدو نه وساتل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5326, 'Deuteronomy 32:12', 'Deuteronomy', 32, 12, '&nbsp;يواځې مالِک خُدائ د خپلو خلقو لارښودنه وکړه د هغۀ سره د پردى خُدائ مدد نۀ وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5327, 'Deuteronomy 32:13', 'Deuteronomy', 32, 13, '&nbsp;هغۀ دا موقع ورکړه چې په اوچتو مُلکونو حکومت وکړى، او هغوئ له يې د پټو د فصلونو خوراک ورکړو په هغوئ يې د يو ګټ نه شات وخوړل، د کاڼى په شان سختې زمکې نه يې د زيتُونو تېل ورکړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5328, 'Deuteronomy 32:14', 'Deuteronomy', 32, 14, '&nbsp;د رَمو نه يې ماستۀ او پئ او د ګډُورى لم ورکړل، د بسن ښۀ ګډُورى او چېلى او ښۀ غنم يې ورکړل. د انګورو رس نه تاسو مے وڅښل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5329, 'Deuteronomy 32:15', 'Deuteronomy', 32, 15, '&nbsp;د مالِک خُدائ خلق مالداره شول، خو سرکشه وُو، هغوئ څاربۀ او په خوراک ماړۀ وُو. هغوئ خُدائ پاک خپل خالِق پرېښودو هغوئ د خپل طاقتور خلاصوونکى نه منکر شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5330, 'Deuteronomy 32:16', 'Deuteronomy', 32, 16, '&nbsp;د هغوئ بُت پرستۍ د مالِک خُدائ غېرت رابېدار کړو، د هغوئ حرام کار هغه په قهر کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5331, 'Deuteronomy 32:17', 'Deuteronomy', 32, 17, '&nbsp;هغوئ پيريانو ته قربانۍ وکړې او خُدائ پاک ته يې ونۀ کړې، هغه معبودان چې هغوئ نۀ دى پېژندلى، هغه معبودان چې اوس اوس راوتلى دى چې ستاسو پلار نيکۀ د دې نه هيڅکله نۀ دى يرېدلى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5332, 'Deuteronomy 32:18', 'Deuteronomy', 32, 18, '&nbsp;هغوئ خپل خُدائ پاک خپل خلاصونکے هېر کړو، چا چې هغوئ له ژوند ورکړے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5333, 'Deuteronomy 32:19', 'Deuteronomy', 32, 19, '&nbsp;کله چې مالِک خُدائ دا وليدل، هغه په قهر وو او د خپلو زامنو او لوڼو نه منکر شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5334, 'Deuteronomy 32:20', 'Deuteronomy', 32, 20, '&nbsp;هغۀ وفرمائيل، ”زۀ به د هغوئ نه مخ واړوم، بيا به زۀ وګورم چې په هغوئ باندې څۀ کيږى، ځکه چې هغه يو ضدى نسل دے، څوک چې بې‌وفا دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5335, 'Deuteronomy 32:21', 'Deuteronomy', 32, 21, '&nbsp;د خپلو غلطو بُتانو په وجه هغوئ زۀ په قهر کړے يم، د بې‌کاره معبودانو په وجه هغوئ زما غېرت راپارولے دے، زۀ به هغوئ د هغه خلقو په وجه په حسد کړم څوک چې قوم نۀ دى، نو زۀ به د يو کم عقل قوم په ذريعه هغوئ په قهر کړم،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5336, 'Deuteronomy 32:22', 'Deuteronomy', 32, 22, '&nbsp;زما قهر به د اور په شان لمبې ووهى او په زمکه باندې هر څيز به وسوزوى. دا به لاندې دُنيا ته ورسيږى او د غرونو بېخونه به تباه کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5337, 'Deuteronomy 32:23', 'Deuteronomy', 32, 23, '&nbsp;زۀ به په هغوئ باندې نۀ ختمېدونکى افتونه راولم او د هغوئ خِلاف به خپل ټول غشى استعمال کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5338, 'Deuteronomy 32:24', 'Deuteronomy', 32, 24, '&nbsp;هغوئ به د لوږې او تبې نه مړۀ شى، هغوئ به په دې سختو وباګانو مړۀ شى. زۀ به ځنګلى ځناور ورولېږم چې په هغوئ حمله وکړى، او زهرژن ماران به ورولېږم چې هغوئ وچيچى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5339, 'Deuteronomy 32:25', 'Deuteronomy', 32, 25, '&nbsp;د جنګ په وجه به په کوڅو کښې مړى پراتۀ وى، په کورونو کښې به يره وى. پېغلې او ځوانان به مړۀ شى، نۀ به ماشومان او نۀ به سپين‌ږيرى بچ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5340, 'Deuteronomy 32:26', 'Deuteronomy', 32, 26, '&nbsp;ما به هغوئ بېخى تباه کړى وى، نو هيڅ څوک به هغوئ نۀ يادوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5341, 'Deuteronomy 32:27', 'Deuteronomy', 32, 27, '&nbsp;خو د هغوئ دشمنان ما داسې لافو وهلو ته پرې نۀ ښودل چې هغوئ زما خلقو له شکست ورکړے وے، ځکه چې هغوئ ما په خپله ختم کړى دى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5342, 'Deuteronomy 32:28', 'Deuteronomy', 32, 28, '&nbsp;بنى اِسرائيل يو داسې قوم دے چې شعور نۀ لرى، هغوئ بېخى عقل نۀ لرى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5343, 'Deuteronomy 32:29', 'Deuteronomy', 32, 29, '&nbsp;کاش چې هغوئ هوښيار وے او په دې باندې پوهېدلے، کاش چې هغوئ په خپل اَنجام باندې پوهه شوى وے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5344, 'Deuteronomy 32:30', 'Deuteronomy', 32, 30, '&nbsp;ولې زرو کسانو د يو کس نه شکست وخوړو، او ولې لسو زرو صِرف دوه کسانو نه شکست وخوړو؟ مالِک خُدائ، د هغوئ خُدائ پاک، هغوئ پرېښى وُو، خُدائ تعالىٰ د هغوئ نه مخ اړولے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5345, 'Deuteronomy 32:31', 'Deuteronomy', 32, 31, '&nbsp;د هغوئ دشمنانو ته پته ده چې د هغوئ معبودان کمزورى دى، د بنى اِسرائيلو د خُدائ پاک په شان طاقتور نۀ دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5346, 'Deuteronomy 32:32', 'Deuteronomy', 32, 32, '&nbsp;د هغوئ دشمنان د سدوم او عموره په شان خراب شوى دى، هغوئ د داسې باغونو په شان دى چې تراخۀ او زهرژن انګور نيسى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5347, 'Deuteronomy 32:33', 'Deuteronomy', 32, 33, '&nbsp;د داسې ميو په شان چې د مارانو د زهرو نه جوړ وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5348, 'Deuteronomy 32:34', 'Deuteronomy', 32, 34, '&nbsp;د مالِک خُدائ په ياد دى چې د هغوئ دشمنانو څۀ کړى دى، هغه د صحيح وخت اِنتظار کوى چې هغوئ له سزا ورکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5349, 'Deuteronomy 32:35', 'Deuteronomy', 32, 35, '&nbsp;مالِک خُدائ فرمائى چې بدل اخستل زما کار دے، بدل به زۀ اخلم. نو هغه وخت به راشى چې هغوئ به راوغورزيږى، او د هغوئ د تباهۍ ورځ نزدې ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5350, 'Deuteronomy 32:36', 'Deuteronomy', 32, 36, '&nbsp;مالِک خُدائ به خپل خلق بچ کړى کله چې هغه ووينى چې د هغوئ طاقت ختم شو. هغه به په هغوئ رحم وکړى څوک چې د هغۀ خِدمت کوى، کله چې وګورى چې هغوئ څومره بې‌مددګاره دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5351, 'Deuteronomy 32:37', 'Deuteronomy', 32, 37, '&nbsp;نو مالِک خُدائ به د خپلو خلقو نه تپوس وکړى، ”هغه تکړه معبودان چرته دى چې تاسو پرې يقين لرلو؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5352, 'Deuteronomy 32:38', 'Deuteronomy', 32, 38, '&nbsp;تاسو د خوراک دپاره هغوئ له د خپلو قربانو وازګه ورکوله او د څښلو دپاره مو ورته مے پېش کول. اوس هغوئ دې راشى او ستاسو مدد دې وکړى، هغوئ دې ستاسو بچ کولو دپاره رامنډه کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5353, 'Deuteronomy 32:39', 'Deuteronomy', 32, 39, '&nbsp;زۀ او يواځې زۀ خُدائ پاک يم، بل يو هم حقيقى خُدائ نشته. زۀ مړۀ کول او ژوندى کول کوم، زۀ زخمى کول او روغول کوم، او هيڅ څوک زما د کارونو مخالفت نۀ شى کولے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5354, 'Deuteronomy 32:40', 'Deuteronomy', 32, 40, '&nbsp;څنګه چې په حقيقت سره زۀ ژوندے خُدائ پاک يم، زۀ خپل لاس اوچتوم او په خپل ذات قسم خورم', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5355, 'Deuteronomy 32:41', 'Deuteronomy', 32, 41, '&nbsp;چې زۀ به خپله ځلېدونکې تُوره تېره کړم او وبه ګورم چې اِنصاف وشى. زۀ به د خپلو دشمنانو نه بدل واخلم او هغوئ له به سزا ورکړم چې څوک زما نه نفرت کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5356, 'Deuteronomy 32:42', 'Deuteronomy', 32, 42, '&nbsp;زما غشى به د هغوئ په وينه کښې ډُوب شى، او زما تُوره به هغه ټول ووژنى څوک چې زما مخالفت کوى. څوک چې زما خِلاف جنګ کوى زۀ هغه يو کس هم نۀ پرېږدم. تر دې پورې چې زخميان او قېديان به هم مړۀ شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5357, 'Deuteronomy 32:43', 'Deuteronomy', 32, 43, '&nbsp;قومونو، تاسو د مالِک خُدائ د خلقو صِفت وکړئ، مالِک خُدائ هغه هر چا له سزا ورکوى چې څوک هغوئ ووژنى. هغه د خپلو دشمنانو نه بدله اخلى او د خپلو خلقو د زمکې کفاره ادا کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5358, 'Deuteronomy 32:44', 'Deuteronomy', 32, 44, '&nbsp;موسىٰ او د نون زوئ يشوَع د دې حمد ټولې خبرې بيان کړې، د دې دپاره چې د بنى اِسرائيلو خلق يې واورى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5359, 'Deuteronomy 32:45', 'Deuteronomy', 32, 45, '&nbsp;کله چې موسىٰ د خُدائ پاک خبرې د خلقو سره ختمې کړې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5360, 'Deuteronomy 32:46', 'Deuteronomy', 32, 46, '&nbsp;هغۀ دا هم وفرمائيل، ”ما چې نن کومې خبرې تاسو سره کړې دى دا ټولې په زړۀ کښې واچوئ. د يو حُکم په توګه يې خپلو بچو ته وښايئ چې هغوئ د دې نصيحتُونو هره خبره ومنى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5361, 'Deuteronomy 32:47', 'Deuteronomy', 32, 47, '&nbsp;دا د لارښودنې هسې تشې خبرې نۀ دى، دا ستاسو د ژوند خبرې دى. دا ومنئ نو تاسو به په هغه مُلک کښې ډېره موده تېره کړئ چې د اُردن سيند نه پورې دے او تاسو يې قبضه کوئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5362, 'Deuteronomy 32:48', 'Deuteronomy', 32, 48, '&nbsp;هم په هغه ورځ مالِک خُدائ موسىٰ ته وفرمائيل،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5363, 'Deuteronomy 32:49', 'Deuteronomy', 32, 49, '&nbsp;”د موآب په مُلک کښې د عباريم غرونو ته لاړ شه چې د يريحو ښار ته مخامخ دے، د نبو غرۀ ته وخېژه او د کنعان مُلک ته وګوره کوم چې زۀ بنى اِسرائيلو له ورکوم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5364, 'Deuteronomy 32:50', 'Deuteronomy', 32, 50, '&nbsp;تۀ به په هغه غر باندې مړ شې لکه څنګه چې ستا ورور هارون د حُور په غرۀ باندې مړ شوے وو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5365, 'Deuteronomy 32:51', 'Deuteronomy', 32, 51, '&nbsp;ځکه چې د بنى اِسرائيلو په مخکښې تاسو دواړو زما سره بې‌وفائى وکړه. کله چې تاسو د صين په صحرا کښې چې د قادِس ښار سره نزدې دے، د مريبه د چينو سره وئ، نو د خلقو په مخکښې تاسو زما سپکاوے وکړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5366, 'Deuteronomy 32:52', 'Deuteronomy', 32, 52, '&nbsp;تاسو به د يو لرې ځائ نه هغه مُلک وګورئ، خو تاسو به هغه مُلک ته ورننه نۀ وځئ کوم چې زۀ بنى اِسرائيلو له ورکوم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5367, 'Deuteronomy 33:1', 'Deuteronomy', 33, 1, '&nbsp;دا هغه برکتونه دى چې د خُدائ پاک پېغمبر موسىٰ يې د خپل مرګ نه مخکښې د بنى اِسرائيلو دپاره اِعلان وکړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5368, 'Deuteronomy 33:2', 'Deuteronomy', 33, 2, '&nbsp;هغۀ وفرمائيل، ”مالِک خُدائ د سينا غر نه راغلو، هغه په ادوم باندې د نمر په شان راوختلو او د فاران غر نه په خپلو خلقو باندې وځلېدو. لس زره فرښتې د هغۀ سره وې، او په ښى لاس کښې يې د اور لمبه وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5369, 'Deuteronomy 33:3', 'Deuteronomy', 33, 3, '&nbsp;مالِک خُدائ د خپلو خلقو سره مينه کوى او هغه د خپلو مقدسينو حفاظت کوى. نو هغوئ د هغۀ په نقش قدم روان دى او د هغۀ حُکمونه منى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5370, 'Deuteronomy 33:4', 'Deuteronomy', 33, 4, '&nbsp;د هغۀ قانون منو چې موسىٰ مونږ له راکړے دے، چې دا زمونږ د قوم د ټولو نه قيمتى سرمايه ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5371, 'Deuteronomy 33:5', 'Deuteronomy', 33, 5, '&nbsp;مالِک خُدائ د خپلو خلقو بنى اِسرائيلو بادشاه شو کله چې د هغوئ قبيلې او مشران يو ځائ راغونډ وُو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5372, 'Deuteronomy 33:6', 'Deuteronomy', 33, 6, '&nbsp;موسىٰ د روبين قبيلې په حقله داسې وفرمائيل، ”روبين دې ژوندے وى او هيڅکله دې نۀ مرى، اګر چې د هغوئ خلق لږ دى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5373, 'Deuteronomy 33:7', 'Deuteronomy', 33, 7, '&nbsp;د يهوداه قبيلې په حقله هغۀ وفرمائيل، ”مالِکه خُدايه، د مدد دپاره د هغوئ چغې واوره، هغوئ يو ځل بيا د نورو قبيلو سره يو موټے کړه. مالِکه خُدايه، د هغوئ دپاره وجنګېږه، او د هغوئ د دشمنانو خِلاف د هغوئ مدد وکړه.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5374, 'Deuteronomy 33:8', 'Deuteronomy', 33, 8, '&nbsp;د ليوى قبيلې په حقله هغۀ وفرمائيل، ”مالِکه خُدايه، تۀ خپله رضا د اُوريم او تميم په ذريعه څرګندوې د خپلو وفادارو خِدمتګارانو، ليويانو په ذريعه، هغوئ تا په مسه کښې وآزمائيل او د مريبه چينو سره دې رښتونى ثابت کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5375, 'Deuteronomy 33:9', 'Deuteronomy', 33, 9, '&nbsp;هغوئ تا ته د مور پلار، وروڼو او بچو نه هم زياته وفادارى وښودله. هغوئ ستا حُکمونه ومنل او هغوئ ستا د لوظ وفادار وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5376, 'Deuteronomy 33:10', 'Deuteronomy', 33, 10, '&nbsp;هغوئ به ستا خلقو ته وښائى چې ستا د قانون تابعدارى وکړى، هغوئ به ستا په قربان‌ګاه باندې قربانۍ پېش کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5377, 'Deuteronomy 33:11', 'Deuteronomy', 33, 11, '&nbsp;مالِکه خُدايه، د هغوئ د قبيلې مدد وکړه چې تکړه شى، د هغوئ د کارونو نه خوشحاله شه. د هغوئ دشمنان ختم کړه، او مۀ يې پرېږده چې بيا سر راپورته کړى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5378, 'Deuteronomy 33:12', 'Deuteronomy', 33, 12, '&nbsp;د بنيامين قبيلې په حقله هغۀ وفرمائيل، ”دا هغه قبيله ده چې مالِک خُدائ ورسره مينه کوى او ساتنه يې کوى، هغه ټوله ورځ د هغوئ حِفاظت کوى، او هغه د هغوئ په مينځ کښې اوسيږى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5379, 'Deuteronomy 33:13', 'Deuteronomy', 33, 13, '&nbsp;د يوسف قبيلې په حقله هغۀ وفرمائيل، ”مالِک خُدائ دې د باران سره د هغوئ مُلک له برکت ورکړى او لاندې د زمکې نه د اوبو برکت ورکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5380, 'Deuteronomy 33:14', 'Deuteronomy', 33, 14, '&nbsp;مالِک خُدائ دې د هغوئ مُلک له په نمر پَخو شوو مېوو سره برکت ورکړى، د هغوئ مُلک دې د هر موسم د ډېرو ښو مېوو سره ښۀ کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5381, 'Deuteronomy 33:15', 'Deuteronomy', 33, 15, '&nbsp;د هغوئ پخوانى غرونه دې د ښو مېوو په ونو باندې شنۀ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5382, 'Deuteronomy 33:16', 'Deuteronomy', 33, 16, '&nbsp;د هغوئ مُلک دې د ټولو نعمتونو نه ډک شى، مالِک خُدائ دې د خپل خېر سره هغوئ له برکت ورکړى، چا چې د سوزېدونکې بوټى نه خبرې وکړې. دا برکتونه دې د يوسف په قبيله نازل شى، ځکه چې هغه د خپلو وروڼو نه اوچت وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5383, 'Deuteronomy 33:17', 'Deuteronomy', 33, 17, '&nbsp;يوسف د غوَيى په شان طاقت لرى، د ځنګلى غوَيى د ښکرو په شان دے. د هغۀ ښکرونه د منسى زرګونو خلق دى او د اِفرائيم لس زره په زرګونو خلق دى. د دې ښکرو سره هغه قومونه وهى او د دُنيا آخرى سرونو ته يې رسوى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5384, 'Deuteronomy 33:18', 'Deuteronomy', 33, 18, '&nbsp;د زبولون او يساکار قبيلو په حقله هغۀ وفرمائيل، ”زبولون دې په سمندرى کاروبار کښې مالداره شى، او د يساکار دولت دې په کور کښې زيات شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5385, 'Deuteronomy 33:19', 'Deuteronomy', 33, 19, '&nbsp;هغوئ مسافر خپل غرۀ ته رابلى او هلته صحيح قربانۍ پېش کوى. هغوئ ته د آباد سمندر نه دولت ملاويږى او د شګو نه ورته پټه خزانه ملاويږى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5386, 'Deuteronomy 33:20', 'Deuteronomy', 33, 20, '&nbsp;د جاد قبيلې په حقله هغۀ وفرمائيل، ”د خُدائ پاک ثناء صِفت دې وى، چا چې د هغوئ علاقه لويه کړه. جاد د ازمرى په شان اِنتظار کوى چې د ښکار مټ او کوپړۍ غوڅه کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5387, 'Deuteronomy 33:21', 'Deuteronomy', 33, 21, '&nbsp;هغوئ د ځان دپاره د ټولو نه ښۀ زمکه واخستله، د يو مشر برخه د هغوئ په حواله شوه. هغوئ د مالِک خُدائ حُکمونه او قانون ومنلو کله چې د بنى اِسرائيلو مشران يو ځائ راغونډ وُو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5388, 'Deuteronomy 33:22', 'Deuteronomy', 33, 22, '&nbsp;د دان قبيلې په حقله هغۀ وفرمائيل، ”دان د يو ځوان ازمرى په شان دے، چې د بسن نه ټوپ وهى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5389, 'Deuteronomy 33:23', 'Deuteronomy', 33, 23, '&nbsp;د نفتالى قبيلې په حقله هغۀ وفرمائيل، ”د نفتالى سره د مالِک خُدائ د نېکۍ ډېر برکت دے، د هغوئ مُلک به په جنوب کښې د ګليل ډنډ پورې رسيږى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5390, 'Deuteronomy 33:24', 'Deuteronomy', 33, 24, '&nbsp;د آشر قبيلې په حقله هغۀ وفرمائيل، ”آشر ته د نورو قبيلو نه زيات برکت ورکړے شوے دے. هغه به په خپلو وروڼو کښې د ټولو نه ګران وى، او د زيتُونو ونې به د هغۀ په مُلک کښې ښې ډېرې وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5391, 'Deuteronomy 33:25', 'Deuteronomy', 33, 25, '&nbsp;د هغۀ د ښارونو دې د اوسپنې په دروازو سره حِفاظت وشى، او هغه دې همېشه په امن کښې ژوند تېروى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5392, 'Deuteronomy 33:26', 'Deuteronomy', 33, 26, '&nbsp;اے بنى اِسرائيلو، ستاسو د خُدائ پاک په شان خُدائ نشته، د خپل شان سره هغه پاس په آسمان کښې دے، ستاسو د مدد دپاره هغه په وريځو سور راځى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5393, 'Deuteronomy 33:27', 'Deuteronomy', 33, 27, '&nbsp;خُدائ پاک همېشه ستاسو د حِفاظت ځائ دے، د هغۀ ابدى قوت به ستاسو مدد کوى. تاسو چې مخ په وړاندې ځئ نو هغه ستاسو دشمنان شړى، او تاسو ته يې وفرمائيل چې، هغوئ ټول تباه کړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5394, 'Deuteronomy 33:28', 'Deuteronomy', 33, 28, '&nbsp;نو د يعقوب اولاده، په امن سره اوسېږئ، په هغه مُلک کښې په حِفاظت کښې اوسئ چې د غلې او د ميو نه ډک دے، چرته چې د آسمان نه پرخه زمکه اوبۀ کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5395, 'Deuteronomy 33:29', 'Deuteronomy', 33, 29, '&nbsp;اِسرائيلو، تاسو څومره خوشحاله يئ. ستاسو په شان هيڅ څوک هم نشته، يو داسې قوم چې مالِک خُدائ خلاصون ورکړے دے. مالِک خُدائ په خپله ستاسو ډال او ستاسو تُوره دے، چې ستاسو حِفاظت وکړى او تاسو له فتح درکړى. ستاسو دشمنان به راشى او د رحم دپاره به سوال کوى، او تاسو به هغوئ د پښو لاندې کړئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5396, 'Deuteronomy 34:1', 'Deuteronomy', 34, 1, '&nbsp;بيا موسىٰ د موآب د مېدانونو نه د نبو غرۀ ته وختلو، کوم چې د پِسګه غر سر ته چې يريحو ته مخامخ دے، او هلته مالِک خُدائ هغۀ ته هغه ټول مُلک وښودلو يعنې د دان ښار پورې د جِلعاد علاقه يې ورته وښودله،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5397, 'Deuteronomy 34:2', 'Deuteronomy', 34, 2, '&nbsp;د نفتالى ټوله علاقه، د اِفرائيم او منسى علاقې، د مديترانى د سمندر پورې د يهوداه علاقه،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5398, 'Deuteronomy 34:3', 'Deuteronomy', 34, 3, '&nbsp;د صحرا برخه، او هغه مېدان چې د ضُعر نه د يريحو پورې رسيږى، چې د کجورو د ونو ښار دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5399, 'Deuteronomy 34:4', 'Deuteronomy', 34, 4, '&nbsp;بيا مالِک خُدائ موسىٰ ته وفرمائيل، ”دا هغه مُلک دے چې ما د دې وعده د اِبراهيم، اِسحاق او يعقوب سره کړې ده چې د هغوئ اولاد له به يې ورکوم. ما د دې کتلو ته پرېښودې خو هلته تلو ته به دې نۀ پرېږدم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5400, 'Deuteronomy 34:5', 'Deuteronomy', 34, 5, '&nbsp;نو چې څنګه مالِک خُدائ فرمائيلى وُو چې موسىٰ د مالِک خُدائ خِدمت کوونکے هلته به د موآب په مُلک کښې مرى نو هم هغه شان وشول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');